# Generated by GitHub Copilot - Oct-05-2026
class PreflightError(RuntimeError):
    """Expose an actionable, secret-free readiness failure before expensive work."""

    def __init__(self, report):
        """Keep the structured report for GUI callers without storing credentials."""
        self.report = report
        messages = []
        for name, capability in report["capabilities"].items():
            if capability["status"] == "ERROR":
                failures = ", ".join(key for key, check in capability["checks"].items()
                                     if check.get('required',True) and not check.get("ok", False))
                messages.append(f"{name}: {failures}. {capability['action']}")
        super().__init__("Preflight reprovado: " + "; ".join(messages))


# Generated by GitHub Copilot - Oct-05-2026
def _import_check(name, cfg):
    """Actually import a dependency; optional repair is restricted to this .venv."""
    try:
        module = importlib.import_module(name)
        return {"ok": True, "version": str(getattr(module, "__version__", "unknown"))}
    except Exception as exc:
        failure = {"ok": False, "error": scrub(f"{type(exc).__name__}: {exc}")}
    requirements = {
        "faster_whisper": "requirements.txt", "ctranslate2": "requirements.txt",
        "cv2": "requirements-vision.txt", "mediapipe": "requirements-vision.txt",
        "torch": "requirements-diarization.txt", "torchaudio": "requirements-diarization.txt",
        "torchcodec": "requirements-diarization.txt", "pyannote.audio": "requirements-diarization.txt",
        "ultralytics": "requirements-yolo.txt", "scenedetect": "requirements.txt",
    }
    settings = cfg.get("preflight", {})
    if not settings.get("allow_self_repair") or cfg.get("offline") or name not in requirements:
        return failure
    environment = (ROOT / ".venv").resolve()
    if Path(sys.prefix).resolve() != environment or sys.prefix == sys.base_prefix:
        return {**failure, "repair_error": "Reparo permitido apenas na .venv deste projeto."}
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", "-r", str(ROOT / requirements[name])],
                       check=True, capture_output=True, text=True, encoding="utf-8", errors="replace",
                       shell=False, timeout=settings.get("repair_timeout_seconds", 600))
        importlib.invalidate_caches()
        module = importlib.import_module(name)
        return {"ok": True, "version": str(getattr(module, "__version__", "unknown")),
                "repair_requirement": requirements[name]}
    except Exception as exc:
        return {**failure, "repair_error": scrub(f"{type(exc).__name__}: {exc}")}


# Generated by GitHub Copilot - Oct-05-2026
def _file_check(value, checksum=False):
    """Check configured assets without downloading weights or following instructions."""
    path = asset_path(value) if value else None
    present = bool(path and path.is_file() and path.stat().st_size > 0)
    result = {"ok": present, "path": str(path) if path else None}
    if present:
        result["bytes"] = path.stat().st_size
        if checksum:
            result["sha256"] = file_hash(path)
    return result


# Generated by GitHub Copilot - Oct-05-2026
def model_directory_fingerprint(path):
    """Hash model/config assets when local, recording exact files instead of a guessed version."""
    folder=Path(path)
    if not folder.is_dir():
        return None
    selected=[file for file in folder.rglob('*') if file.is_file() and
              (file.suffix in ('.bin','.safetensors','.yaml','.yml','.json','.model','.txt') or file.name=='pytorch_model.bin')]
    return digest({file.relative_to(folder).as_posix():file_hash(file) for file in sorted(selected)}) if selected else None


