def validate_pipeline_model(cfg):
    """Actually load configured pyannote assets, releasing model memory immediately."""
    pipeline=None
    model=cfg['diarization']['model']
    local=asset_path(model)
    token=os.environ.get('HF_TOKEN') or os.environ.get('HUGGING_FACE_HUB_TOKEN')
    try:
        from pyannote.audio import Pipeline
        import torch
        with contextlib.redirect_stdout(io.StringIO()),contextlib.redirect_stderr(io.StringIO()):
            pipeline=Pipeline.from_pretrained(str(local) if local.is_dir() or local.is_file() else model,token=token)
            if pipeline is None:
                raise ValueError('Community-1 nao carregou; verifique cache, token e aceite do modelo.')
            if cfg['device']=='cuda':
                if not torch.cuda.is_available():
                    raise ValueError('CUDA solicitada nao esta disponivel no torch.')
                pipeline.to(torch.device('cuda'))
        return {'ok':True,'model_load':'verified_assets_and_config','device_requested':cfg['device'],
                'inference_executed':False,'token_present':bool(token)}
    except Exception as exc:
        return {'ok':False,'model_load':'failed','error':scrub(f'{type(exc).__name__}: {exc}'),
                'inference_executed':False,'token_present':bool(token)}
    finally:
        pipeline=None
        gc.collect()


# Generated by GitHub Copilot - Oct-05-2026
def _model_access(cfg):
    """Verify a gated model with a small real request, or complete local assets offline."""
    model = cfg["diarization"]["model"]
    local = asset_path(model)
    token = os.environ.get("HF_TOKEN") or os.environ.get("HUGGING_FACE_HUB_TOKEN")
    result = {"model": model, "token_present": bool(token), "cached_model": False,
              "online_access": "not_checked", "ok": False}
    try:
        if local.is_dir():
            snapshot = local
        else:
            from huggingface_hub import snapshot_download
            try:
                snapshot = Path(snapshot_download(model, local_files_only=True))
            except Exception:
                snapshot = None
        if snapshot:
            config_present = (snapshot / "config.yaml").is_file()
            weights_present = any(snapshot.rglob("*.bin")) or any(snapshot.rglob("*.safetensors"))
            result["cached_model"] = bool(config_present and weights_present)
            result["local_model_path"] = str(snapshot)
            result['model_fingerprint']=model_directory_fingerprint(snapshot)
        if local.is_dir() or cfg.get("offline") or not token:
            result["ok"] = result["cached_model"]
            result["online_access"] = "offline" if cfg.get("offline") else "not_checked"
            if not result["ok"]:
                result["error"] = "Modelo local incompleto ou token/aceite HF ausente."
            else:
                result.update(validate_pipeline_model(cfg))
            return result
        from huggingface_hub import hf_hub_download
        config_path=hf_hub_download(model, "config.yaml", token=token,
                        etag_timeout=cfg.get("preflight", {}).get("network_timeout_seconds", 5))
        result.update(ok=True, online_access="verified_config_access")
        result['model_fingerprint']=digest({'config_sha256':file_hash(config_path),
                           'snapshot_revision':Path(config_path).parent.name,
                           'cached_assets':model_directory_fingerprint(Path(config_path).parent)})
    except Exception as exc:
        result.update(error=scrub(f"{type(exc).__name__}: {exc}"), online_access="error")
    if result['ok']:
        result.update(validate_pipeline_model(cfg))
    return result


