def validate_vision_assets(cfg):
    """Open enabled face/landmark/body models before any media download or decode."""
    models={}
    detector=recognizer=landmarker=body=None
    try:
        import cv2
        vision=cfg['vision']
        detector=cv2.FaceDetectorYN.create(str(asset_path(vision['yunet_model'])), '', (320,320))
        recognizer=cv2.FaceRecognizerSF.create(str(asset_path(vision['sface_model'])), '')
        models.update(yunet={'ok':detector is not None},sface={'ok':recognizer is not None})
        if vision['active_speaker']:
            from .vision import LipEngine
            landmarker=LipEngine(vision)
            models['face_landmarker']={'ok':True}
        if vision['body_detection'] and vision['body_backend']=='yolo':
            from ultralytics import YOLO
            body=YOLO(str(asset_path(vision['yolo_model'])))
            models['yolo']={'ok':True}
        return {'ok':all(model['ok'] for model in models.values()),'models':models,'inference_executed':False}
    except Exception as exc:
        return {'ok':False,'error':scrub(f'{type(exc).__name__}: {exc}'),'models':models,'inference_executed':False}
    finally:
        if landmarker:
            landmarker.close()
        detector=recognizer=body=None
        gc.collect()


# Generated by GitHub Copilot - Oct-05-2026
def _output_check(output):
    """Probe the requested output filesystem and release the temporary handle."""
    folder = Path(output).expanduser().resolve()
    try:
        folder.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryFile(dir=folder) as handle:
            handle.write(b"preflight")
            handle.flush()
        return {"ok": True, "path": str(folder)}
    except OSError as exc:
        return {"ok": False, "path": str(folder), "error": scrub(exc)}


