def run_preflight(cfg, output=None):
    """Return independent enabled-capability checks; never include token values."""
    capabilities = {}

    def register(name, enabled, checks, action):
        """Keep disabled optional capabilities from affecting the readiness verdict."""
        capabilities[name] = {"enabled": bool(enabled), "required": bool(enabled),
                              "status": ("READY" if all(check.get("ok", False) for check in checks.values() if check.get('required',True))
                                         else "ERROR") if enabled else "DISABLED",
                              "checks": checks, "action": action}

    transcription = cfg["transcription"]
    if transcription.get("import_file"):
        asr = {"import_file": _file_check(transcription["import_file"])}
    else:
        asr = {name: _import_check(name, cfg) for name in ("faster_whisper", "ctranslate2")}
        asr['configuration']={'ok':True,'model':transcription['model'],'device':cfg['device'],'compute_type':cfg['compute_type']}
        local_asr=asset_path(transcription['model'])
        asr['configuration']['model_fingerprint']=model_directory_fingerprint(local_asr) if local_asr.is_dir() else None
        from .gpu_runtime import ctranslate2_cuda_info
        from .ollama_local import nvidia_smi
        runtime = ctranslate2_cuda_info()
        nvidia=nvidia_smi() if cfg['device']!='cpu' else {'available':False,'gpus':[]}
        needs_cuda=cfg['device']=='cuda' or (cfg['device']=='auto' and nvidia.get('available') and not transcription.get('allow_cpu_fallback',False))
        cuda_ready=(runtime.get('device_count') or 0)>0 and not runtime.get('compute_types_error') and (
                   sys.platform!='win32' or runtime.get('dll_status',{}).get('status')=='available')
        asr['cuda']={'ok':not needs_cuda or cuda_ready,'device':cfg['device'],'runtime':runtime,'nvidia':nvidia,
                     'cpu_fallback_allowed':transcription.get('allow_cpu_fallback',False)}
        if cfg.get('offline'):
            model=asset_path(transcription['model'])
            cached=model.is_dir() and (model/'model.bin').is_file()
            if not cached and asr['faster_whisper']['ok']:
                try:
                    from faster_whisper.utils import download_model
                    cached_path=Path(download_model(transcription['model'],output_dir=str(ROOT/'models'/'whisper'),local_files_only=True))
                    cached=(cached_path/'model.bin').is_file()
                except Exception:
                    cached=False
            asr['offline_model']={'ok':cached,'cached':cached,'inference_executed':False}
    register("asr", True, asr, "Instale requirements.txt; valide CUDA ou selecione CPU explicitamente.")

    diarization = cfg["diarization"]
    diar_checks = {}
    if diarization["enabled"]:
        if diarization.get("import_file"):
            diar_checks["import_file"] = _file_check(diarization["import_file"])
        else:
            diar_checks = {name: _import_check(name, cfg) for name in ("torch", "torchaudio", "pyannote.audio")}
            try:
                version = importlib.metadata.version("pyannote.audio")
            except importlib.metadata.PackageNotFoundError:
                version = "4"
            if int(version.split(".")[0]) >= 4:
                diar_checks["torchcodec"] = _import_check("torchcodec", cfg)
                diar_checks['torchcodec'].update(required=False,input_contract='in_memory_waveform_and_sample_rate',
                                                decoder_needed_by_current_pipeline=False,
                                                note='Importacao diagnosticada; a pipeline nao usa decoder de arquivo torchcodec.')
            diar_checks["model_access"] = _model_access(cfg)
            if diar_checks["torch"]["ok"]:
                import torch
                diar_checks["cuda"] = {"ok": cfg["device"] != "cuda" or torch.cuda.is_available(),
                                       "available": bool(torch.cuda.is_available()), "requested": cfg["device"]}
    register("diarization", diarization["enabled"], diar_checks,
             "Instale requirements-diarization.txt; aceite Community-1 no HF e forneca token apenas em memoria, ou cache local completo.")

    vision = cfg["vision"]
    vision_checks = {}
    if vision["enabled"]:
        vision_checks["opencv"] = _import_check("cv2", cfg)
        for name in ("yunet_model", "sface_model"):
            vision_checks[name] = _file_check(vision[name], checksum=True)
        if vision["active_speaker"]:
            vision_checks["mediapipe"] = _import_check("mediapipe", cfg)
            vision_checks["landmarker_model"] = _file_check(vision["landmarker_model"], checksum=True)
        if vision["body_detection"]:
            if vision["body_backend"] == "yolo":
                vision_checks["yolo"] = _import_check("ultralytics", cfg)
                vision_checks["yolo_model"] = _file_check(vision["yolo_model"], checksum=True)
            else:
                try:
                    import cv2
                    vision_checks["hog"] = {"ok": hasattr(cv2, "HOGDescriptor")}
                except Exception as exc:
                    vision_checks["hog"] = {"ok": False, "error": scrub(exc)}
        if vision_checks and all(check.get('ok') for check in vision_checks.values()):
            vision_checks['model_load']=validate_vision_assets(cfg)
    register("vision", vision["enabled"], vision_checks,
             "Instale requirements-vision.txt e execute scripts/download_models.py antes da analise.")

    sem = cfg["semantic_analysis"]
    sem_checks = {}
    if sem["enabled"] and sem["backend"] == "ollama":
        from .ollama_local import service_info, profile_options
        info = service_info(sem["ollama_url"], timeout=cfg.get("preflight", {}).get("network_timeout_seconds", 5))
        names = [entry.get("name") for entry in info.get("models", [])]
        requested = sem["model"] if ":" in sem["model"] else sem["model"] + ":latest"
        sem_checks = {"ollama": {"ok": bool(info.get("reachable")), "error": scrub(info.get("error") or "")},
                      "model": {"ok": sem["model"] in names or requested in names, "configured": sem["model"], "installed": names,
                                "model_fingerprint":next((entry.get('digest') for entry in info.get('models',[]) if entry.get('name') in (sem['model'],requested)),None)},
                      "profile": {"ok": True, "profile": sem["profile"], "effective_options": profile_options(sem),
                                  "runtime": info.get("running", [])}}
    register("semantic", sem["enabled"], sem_checks,
             "Inicie Ollama e instale o modelo configurado, ou selecione heuristic explicitamente.")
    register("scenes", cfg["scenes"]["enabled"],
             {"scenedetect": _import_check("scenedetect", cfg)} if cfg["scenes"]["enabled"] else {},
             "Instale requirements.txt para deteccao de cortes.")

    for name, module in (("ocr", "pytesseract"), ("audio_events", "panns_inference")):
        enabled = cfg[name]["enabled"]
        checks = {"import": _import_check(module, cfg)} if enabled else {}
        if enabled and name == "ocr":
            checks["tesseract"] = {"ok": bool(cfg[name].get("tesseract_cmd") or shutil.which("tesseract"))}
        if enabled and name == "audio_events":
            checks["checkpoint"] = _file_check(cfg[name].get("checkpoint"))
        register(name, enabled, checks, f"Instale e configure requirements-{name.replace('_', '-')}.txt.")

    camera = {name: {"ok": bool(shutil.which(name)), "path": shutil.which(name)} for name in ("ffmpeg", "ffprobe")}
    try:
        from jsonschema.validators import validator_for
        for path in (ROOT / "schemas").glob("*.schema.json"):
            schema = json.loads(path.read_text(encoding="utf-8-sig"))
            validator_for(schema).check_schema(schema)
        camera["schemas"] = {"ok": True}
    except Exception as exc:
        camera["schemas"] = {"ok": False, "error": scrub(exc)}
    if cfg["preview"]["enabled"]:
        camera["preview_opencv"] = _import_check("cv2", cfg)
    register("camera_preview", True, camera, "Disponibilize FFmpeg/ffprobe no PATH e schemas validos.")
    register("export", True, {"output": _output_check(output or ROOT / "analysis"),
                              "redaction": {"ok": scrub("hf_" + "x" * 24) != "hf_" + "x" * 24}},
             "Use uma pasta de saida gravavel; nenhum token deve entrar em outputs.")
    ready = all(item["status"] != "ERROR" for item in capabilities.values())
    return {"schema_version": "1.0", "status": "READY" if ready else "ERROR", "ready": ready,
            "python": sys.version.split()[0], "python_executable": sys.executable,
            "target_runtime": {"os": "Windows 10/11", "python": "3.11.x"},
            "runtime_target_match": sys.platform == "win32" and sys.version_info[:2] == (3, 11),
            "offline": bool(cfg.get("offline")), "capabilities": capabilities,
            "compact_artifacts_available": (ROOT / "src" / "ldporto" / "compact_artifacts.py").is_file()}


# Generated by GitHub Copilot - Oct-05-2026
def require_preflight(cfg, output=None):
    """Abort an enabled-capability failure before download, audio, ASR or vision."""
    report = run_preflight(cfg, output)
    if not report["ready"]:
        raise PreflightError(report)
    return report